js='const IsabelleSymbols='+json.dumps(data('presentation/isabelle-symbols.json'),ensure_ascii=False).replace('<','\\u003c')+';\n'+read('presentation/syntax.js')+'''
const cases=[...document.querySelectorAll('.program-case')];
const programButtons=[...document.querySelectorAll('[data-program-choice]')];
const proverButtons=[...document.querySelectorAll('[data-prover-choice]')];
let chosenProgram=cases[0].dataset.program,chosenProver='VST';
function selectCase(updateURL=true){
 cases.forEach(c=>{c.hidden=c.dataset.program!==chosenProgram;c.querySelectorAll('.pane').forEach(p=>p.classList.toggle('active',p.dataset.tool===chosenProver));});
 programButtons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.programChoice===chosenProgram)));
 proverButtons.forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.proverChoice===chosenProver));b.querySelector('.case-status').textContent=chosenProgram==='p5_reverse'&&b.dataset.proverChoice==='WP'?'Partial':'Checked';});
 const title=programButtons.find(b=>b.dataset.programChoice===chosenProgram).querySelector('strong').textContent;
 document.querySelector('#selection-status').textContent=title+' · '+chosenProver;
 document.querySelectorAll('.program-case:not([hidden]) .pane.active .proof-player').forEach(p=>{if(p.refresh)p.refresh();});
 fitProofPlayers();
 if(updateURL)history.replaceState(null,'','#'+new URLSearchParams({program:chosenProgram,prover:chosenProver}));
}
function readSelection(){const params=new URLSearchParams(location.hash.slice(1));
 if(programButtons.some(b=>b.dataset.programChoice===params.get('program')))chosenProgram=params.get('program');
 if(proverButtons.some(b=>b.dataset.proverChoice===params.get('prover')))chosenProver=params.get('prover');
 selectCase(false);
}
programButtons.forEach(b=>b.onclick=()=>{chosenProgram=b.dataset.programChoice;selectCase();});
proverButtons.forEach(b=>b.onclick=()=>{chosenProver=b.dataset.proverChoice;selectCase();});
window.addEventListener('hashchange',readSelection);
document.querySelector('#theme').onclick=()=>document.body.classList.toggle('light');
readSelection();
function fitProofPlayers(){
 if(!matchMedia('(min-width:1100px) and (min-height:700px)').matches)return;
 document.querySelectorAll('.program-case:not([hidden]) .pane.active > .replay:first-child[open] .proof-player').forEach(player=>{
  const top=player.getBoundingClientRect().top+window.scrollY;
  player.style.setProperty('--player-height',Math.max(240,window.innerHeight-top-32)+'px');
 });
}
window.addEventListener('resize',fitProofPlayers);
document.querySelectorAll('.replay').forEach(replay=>replay.addEventListener('toggle',fitProofPlayers));
const recordings=JSON.parse(document.querySelector('#proof-recordings').textContent);
document.querySelectorAll('.proof-player').forEach(player=>{
 const rec=recordings[player.dataset.recording], steps=rec.steps;
 const lang=rec.language||'rocq';
 const sourceTokens=LabSyntax.scan(rec.source_text,lang);
 let index=0;
 const firstProof=Math.max(0,steps.findIndex(s=>lang==='isabelle'?s.proof_open:s.command==='Proof.'));
 function render(i){index=Math.max(0,Math.min(steps.length-1,i));const s=steps[index];
  player.querySelector('.proof-position').textContent='Step '+(index+1)+' / '+steps.length;
  LabSyntax.render(player.querySelector('.proof-output'),s.output||(lang==='isabelle'?'(No open proof state after this command. Other command messages are in the recorded build log.)':'(Rocq emitted no message or goal display for this command.)'),lang);
  const context=player.querySelector('.proof-context');context.replaceChildren();
  const before=document.createElement('span');before.className='executed';before.append(LabSyntax.fragment(sourceTokens,0,s.start));
  const current=document.createElement('mark');current.append(LabSyntax.fragment(sourceTokens,s.start,s.end));
  const after=document.createElement('span');after.append(LabSyntax.fragment(sourceTokens,s.end));
  context.append(before,current,after);LabSyntax.lineNumbers(context,rec.source_text);context.scrollTop=Math.max(0,current.getBoundingClientRect().top-context.getBoundingClientRect().top+context.scrollTop-context.clientHeight/3);
  player.querySelector('[data-proof=previous]').disabled=index===0;
  player.querySelector('[data-proof=next]').disabled=index===steps.length-1;
 }
 player.querySelector('[data-proof=previous]').onclick=()=>render(index-1);
 player.querySelector('[data-proof=next]').onclick=()=>render(index+1);
 player.querySelector('[data-proof=reset]').onclick=()=>render(0);
 player.querySelector('[data-proof=proof]').onclick=()=>render(firstProof);
 player.refresh=()=>render(index);
 render(firstProof);
});
let lastProofPlayer=null;
fitProofPlayers();
for(const event of ['pointerdown','focusin'])document.addEventListener(event,e=>{
 const player=e.target.closest?.('.proof-player');if(player)lastProofPlayer=player;
});
document.addEventListener('keydown',e=>{
 if(!['ArrowLeft','ArrowRight'].includes(e.key)||e.altKey||e.ctrlKey||e.metaKey||e.shiftKey)return;
 if(e.target.closest?.('select,input,textarea,[contenteditable]:not([contenteditable="false"])'))return;
 const available=[...document.querySelectorAll('.program-case:not([hidden]) .pane.active .proof-player')].filter(p=>p.getClientRects().length);
 const focused=e.target.closest?.('.proof-player');
 const player=available.includes(focused)?focused:available.includes(lastProofPlayer)?lastProofPlayer:available[0];
 if(!player)return;
 e.preventDefault();
 const button=player.querySelector('[data-proof='+ (e.key==='ArrowLeft'?'previous':'next')+']');
 if(!button.disabled)button.click();
});
'''
