page=page.replace('<a href="#reference">Reference</a>', '<a href="#reference">Reference</a><a href="https://github.com/ExcitedSpider/itp-c-lab" target="_blank" rel="noopener noreferrer">GitHub</a>')
payload=json.dumps(recordings,ensure_ascii=False).replace('<','\\u003c')
page=page.replace('<script>'+js,'<script type="application/json" id="proof-recordings">'+payload+'</script><script>'+js)
(ROOT/'presentation/index.html').write_text(page)
